local parsed = {}
local function Rows(lang)
    if parsed[lang] ~= nil then return parsed[lang] or nil end
    local src = SRC[lang]
    if not src then parsed[lang] = false return nil end
    local chunk = loadstring and loadstring(src) or (load and load(src))
    local ok, rows = pcall(chunk)
    parsed[lang] = ok and type(rows) == "table" and rows or false
    return parsed[lang] or nil
end

local function Apply(lang)
    lang = lang or (FDJ.GetLanguage and FDJ.GetLanguage()) or "enUS"
    local rows = Rows(lang)
    if not rows then return end
    FDJ.ContentLocales = FDJ.ContentLocales or {}
    local content = FDJ.ContentLocales[lang] or {}
    FDJ.ContentLocales[lang] = content
    content.places = content.places or {}
    for en, text in pairs(rows) do
        content.places[en] = text
    end
    FDJ.ContentTextVersion = (FDJ.ContentTextVersion or 0) + 1
end
FDJ.ApplyQuestTextTranslations = Apply

pcall(Apply)

if type(FDJ.SetLanguage) == "function" then
    local baseSetLanguage = FDJ.SetLanguage
    FDJ.SetLanguage = function(...)
        local lang, stored = baseSetLanguage(...)
        pcall(Apply, lang)
        return lang, stored
    end
end

local f = CreateFrame and CreateFrame("Frame")
if f then
    f:RegisterEvent("PLAYER_LOGIN")
    f:SetScript("OnEvent", function() pcall(Apply) end)
end
